<template>
  <div v-if="open" class="column-config-overlay" @click.self="$emit('cancel')">
    <section class="column-config-dialog" role="dialog" aria-modal="true" aria-label="列配置">
      <header class="column-config-heading"><div><h2>列配置</h2><p>选择列并拖动右侧列名调整顺序</p></div><button class="column-config-close" type="button" aria-label="关闭" @click="$emit('cancel')">×</button></header>
      <div class="column-config-body"><section class="column-config-available"><label class="column-config-search"><input v-model="search" type="search" placeholder="搜索列名" /><span>⌕</span></label><div class="column-config-groups"><section v-for="group in groups" :key="group.name" class="column-config-group"><div class="column-group-heading"><span>{{ group.name }}</span><button type="button" @click="toggleGroup(group)">{{ group.headers.every(header => draftVisible.includes(header)) ? '取消' : '全选' }}</button></div><div class="column-option-grid"><label v-for="header in group.headers" :key="header" class="column-option"><input type="checkbox" :checked="draftVisible.includes(header)" @change="toggle(header)" /><span :title="label(header)">{{ label(header) }}</span></label></div></section><p v-if="!groups.length" class="column-config-empty">没有匹配的列</p></div></section><aside class="column-config-selected"><div class="selected-heading"><strong>已选 <span>({{ selected.length }})</span></strong><button type="button" @click="restore">恢复默认</button></div><p class="selected-hint">最多可固定 {{ maxPinned }} 列</p><div class="selected-column-list"><div v-for="(header,index) in selected" :key="header" class="selected-column" :class="{ 'drag-target': dragTarget === header }" draggable="true" @dragstart="startDrag(header)" @dragover.prevent="dragTarget=header" @drop.prevent="drop(header)"><span class="selected-drag-handle" title="拖动排序">⠿</span><span class="selected-index">{{ index + 1 }}</span><span class="selected-name" :title="label(header)">{{ label(header) }}</span><button type="button" class="selected-pin" :class="{ active: draftPinned.includes(header) }" :disabled="!draftPinned.includes(header) && fixedCount + draftPinned.length >= maxPinned" :title="draftPinned.includes(header) ? '取消固定列' : '固定列'" @click="togglePin(header)"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m13.5 2.8 3.7 3.7-2 1.1-.8 3.2-2.1 2.1-2.1-2.1-5.6 5.6-.9-.9 5.6-5.6-2.1-2.1 2.1-2.1 3.2-.8 1-2.1Z" fill="currentColor"/><path d="m10.2 11.5-4.4 4.4" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg></button><button type="button" class="selected-remove" aria-label="移除" @click="toggle(header)">×</button></div><p v-if="!selected.length" class="selected-empty">请从左侧选择要显示的列</p></div><p class="selected-hint">拖动手柄可调整列顺序</p></aside></div>
      <footer class="column-config-footer"><button type="button" @click="restore">恢复默认</button><span>固定列最多 {{ maxPinned }} 项</span><div><button type="button" @click="$emit('cancel')">取消</button><button type="button" class="column-apply" @click="apply">保存并应用</button></div></footer>
    </section>
  </div>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
const props = defineProps({ open:Boolean, headers:{type:Array,default:()=>[]}, visible:{type:Array,default:()=>[]}, pinned:{type:Array,default:()=>[]}, fixedCount:{type:Number,default:0}, maxPinned:{type:Number,default:7}, label:{type:Function,default:value=>value} })
const emit = defineEmits(['cancel','apply'])
const search=ref(''), draftVisible=ref([]), draftOrder=ref([]), draftPinned=ref([]), dragged=ref(''), dragTarget=ref('')
const selected=computed(()=>draftOrder.value.filter(item=>draftVisible.value.includes(item)))
const filteredHeaders=computed(()=>draftOrder.value.filter(item=>!search.value || props.label(item).toLowerCase().includes(search.value.toLowerCase())))
const groups=computed(()=>{ const result=[]; for(const header of filteredHeaders.value){ const name=/id|number|order|sku|date|time/i.test(header)?'基础信息':/amount|total|quantity|fee|price|cost/i.test(header)?'金额与数量':/type|description|status|reason/i.test(header)?'交易信息':'其他信息'; let group=result.find(item=>item.name===name); if(!group){group={name,headers:[]};result.push(group)} group.headers.push(header)} return result })
watch(()=>props.open, open=>{ if(open){draftOrder.value=[...props.headers]; draftVisible.value=props.headers.filter(item=>props.visible.includes(item)); draftPinned.value=props.pinned.filter(item=>props.headers.includes(item)); search.value=''}},{immediate:true})
function toggle(header){draftVisible.value=draftVisible.value.includes(header)?draftVisible.value.filter(item=>item!==header):[...draftVisible.value,header]; if(!draftVisible.value.includes(header)) draftPinned.value=draftPinned.value.filter(item=>item!==header)}
function toggleGroup(group){const all=group.headers.every(header=>draftVisible.value.includes(header)); draftVisible.value=all?draftVisible.value.filter(header=>!group.headers.includes(header)):[...new Set([...draftVisible.value,...group.headers])]}
function togglePin(header){draftPinned.value=draftPinned.value.includes(header)?draftPinned.value.filter(item=>item!==header):[...draftPinned.value,header]}
function startDrag(header){dragged.value=header}
function drop(target){if(!dragged.value||dragged.value===target)return; const order=[...draftOrder.value]; const from=order.indexOf(dragged.value); order.splice(from,1); order.splice(order.indexOf(target),0,dragged.value); draftOrder.value=order; dragged.value=''; dragTarget.value=''}
function restore(){draftOrder.value=[...props.headers]; draftVisible.value=[...props.headers]; draftPinned.value=[]}
function apply(){emit('apply',{order:[...draftOrder.value],visible:[...draftVisible.value],pinned:[...draftPinned.value]})}
</script>
<style scoped>
.column-config-overlay{position:fixed;inset:0;z-index:10010;display:flex;align-items:center;justify-content:center;padding:22px;background:rgb(20 35 50 / 32%);backdrop-filter:blur(2px)}.column-config-dialog{display:flex;flex-direction:column;width:min(1180px,100%);height:min(900px,calc(100dvh - 44px));min-height:360px;overflow:hidden;border:1px solid #dce4ec;border-radius:12px;background:#fff;box-shadow:0 24px 64px rgb(20 35 50 / 22%)}.column-config-heading,.column-config-footer{display:flex;align-items:center;justify-content:space-between;gap:16px}.column-config-heading{padding:20px 24px 16px;border-bottom:1px solid #e8edf2}.column-config-heading h2{margin:0;color:#26384a;font-size:20px}.column-config-heading p{margin:6px 0 0;color:#81909e;font-size:12px}.column-config-close{width:32px;height:32px;border:0;background:transparent;color:#7b8997;font-size:23px}.column-config-body{display:grid;grid-template-columns:minmax(0,1fr) 340px;flex:1;min-height:0}.column-config-available{display:flex;flex-direction:column;min-width:0;min-height:0;padding:20px 24px}.column-config-search{display:flex;align-items:center;gap:10px;height:44px;padding:0 12px;border:1px solid #dce4ec;border-radius:7px;color:#91a0ae}.column-config-search input{width:100%;height:38px;border:0;outline:0;font:inherit}.column-config-groups{flex:1;min-height:0;margin-top:14px;overflow:auto}.column-config-group{padding:12px 0 14px;border-bottom:1px solid #edf1f5}.column-group-heading{display:flex;align-items:center;gap:10px;margin-bottom:11px;color:#8392a0;font-size:12px}.column-group-heading:before{content:'';width:6px;height:6px;border-radius:50%;background:#aab9c7}.column-group-heading button,.selected-heading button{padding:3px 5px;border:0;background:transparent;color:#2677e8;font-size:11px}.column-option-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px 16px}.column-option{display:flex;align-items:center;gap:8px;min-width:0;color:#48596a;font-size:12px}.column-option span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.column-option input{width:15px;height:15px;accent-color:#347df4}.column-config-selected{display:flex;flex-direction:column;min-width:0;min-height:0;padding:22px 18px 12px;border-left:1px solid #e7edf2;background:#fafbfd}.selected-heading{display:flex;align-items:center;justify-content:space-between;color:#27394b;font-size:15px}.selected-heading span{color:#8b98a5;font-weight:500}.selected-hint{margin:10px 0 12px;color:#99a5b0;font-size:12px}.selected-column-list{flex:1;min-height:0;overflow:auto}.selected-column{display:flex;align-items:center;gap:9px;min-height:39px;padding:0 2px;border-bottom:1px solid #f0f3f6;color:#344557;font-size:12px}.selected-column.drag-target{box-shadow:inset 0 2px #347df4;background:#f1f7fd}.selected-drag-handle{color:#aebbc7;font-size:18px;cursor:grab}.selected-index{flex:0 0 18px;color:#7d8b99;text-align:right}.selected-name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.selected-pin{width:27px;height:27px;padding:0;border:1px solid #e1e7ed;border-radius:6px;background:#fff;color:#94a2ae;font-size:13px}.selected-pin.active{border-color:#bad1e3;color:#2e6e9f;background:#eef6fb}.selected-remove{width:24px;height:24px;border:0;background:transparent;color:#8c9aa7;font-size:17px}.selected-empty,.column-config-empty{padding:28px 10px;color:#9aa6b1;text-align:center}.column-config-footer{min-height:64px;padding:10px 20px 10px 24px;border-top:1px solid #e7edf2}.column-config-footer>span{color:#8a98a5;font-size:11px}.column-config-footer>div{display:flex;gap:8px;margin-left:auto}.column-config-footer button{min-width:76px;height:34px;padding:0 13px;border:1px solid #d5dee7;border-radius:6px;background:#fff;color:#536577}.column-config-footer .column-apply{border-color:#1264f5;background:#1264f5;color:#fff}@media(max-width:800px){.column-config-body{grid-template-columns:minmax(0,1fr) 250px}.column-option-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.column-config-overlay{padding:10px}.column-config-dialog{height:calc(100dvh - 20px)}.column-config-body{grid-template-columns:1fr;grid-template-rows:minmax(0,1fr) minmax(180px,38%)}.column-config-available{padding:12px 14px}.column-config-selected{padding:12px 14px;border-top:1px solid #e7edf2;border-left:0}.column-config-heading{padding:14px 16px}.column-config-footer{min-height:56px;padding:8px 12px}.column-config-footer>span{display:none}}
 .selected-pin{display:grid!important;place-items:center;flex:0 0 27px;width:27px!important;height:27px!important;padding:0;border:1px solid #e1e7ed;border-radius:6px;color:#94a2ae;background:#fff}.selected-pin svg{display:block;width:15px;height:15px;transform:rotate(-38deg)}.selected-pin.active{border-color:#bad1e3;color:#2e6e9f;background:#eef6fb}.selected-pin:disabled{opacity:.4;cursor:not-allowed}
</style>
